const provider="HubSpot";
const official="https://api.hubapi.com";
const base=new URL(config.baseUrl??official);
if(base.href!==official+'/'){if(base.protocol!=='http:'||!['127.0.0.1','[::1]'].includes(base.hostname)||base.username||base.password||base.pathname!=='/'||base.search||base.hash)throw new Error('Only explicit loopback HTTP mock baseUrl is permitted');}
const token=context.secrets.get(config.accessTokenSecret??"HUBSPOT_ACCESS_TOKEN");
const segment=v=>{if(v===undefined||v===null||String(v).length===0||String(v).length>500)throw new Error('Missing or oversized provider identifier');return encodeURIComponent(String(v));};
const safeCode=x=>String(x??'provider_error').replace(/[^a-zA-Z0-9_.-]/g,'').slice(0,100);
async function request(path,method='GET',body,read=true){
 const url=new URL(path,base);if(url.origin!==base.origin||url.username||url.password||url.hash)throw new Error('Unsafe provider URL');
 const timeoutMs=config.timeoutMs??15000;if(!Number.isInteger(timeoutMs)||timeoutMs<100||timeoutMs>120000)throw new Error('Invalid timeoutMs');
 const retries=read?(config.readRetries??2):0;if(!Number.isInteger(retries)||retries<0||retries>3)throw new Error('Invalid readRetries');
 for(let attempt=0;;attempt++){
  let response;try{response=await fetch(url,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)}),redirect:'error',signal:AbortSignal.timeout(timeoutMs)});}catch(error){throw new Error(provider+' network/timeout failure'+(read?'':' - external completion uncertain'));}
  let text='';if(response.body){const reader=response.body.getReader();const chunks=[];let bytes=0;try{for(;;){const part=await reader.read();if(part.done)break;bytes+=part.value.byteLength;if(bytes>2000000){await reader.cancel();throw new Error(provider+' response exceeds 2MB byte bound');}chunks.push(part.value);}text=Buffer.concat(chunks).toString('utf8');}catch(error){try{await reader.cancel();}catch{}if(String(error?.message).includes('2MB byte bound'))throw error;throw new Error(provider+' response stream interrupted'+(read?'':' - completion uncertain'));}finally{reader.releaseLock();}}let data;try{data=text?JSON.parse(text):{};}catch{throw new Error(provider+' returned non-JSON HTTP '+response.status);}
  if(response.ok)return data;
  const retryHeader=response.headers.get('retry-after');let delay=retryHeader===null?250*(attempt+1):(/^\d+(?:\.\d+)?$/.test(retryHeader)?Number(retryHeader)*1000:Date.parse(retryHeader)-Date.now());delay=Math.max(0,Math.ceil(Number.isFinite(delay)?delay:250*(attempt+1)));
  if(read&&[429,502,503,504].includes(response.status)&&attempt<retries&&delay<=30000){await context.sleep(delay);continue;}
  throw new Error(provider+' HTTP '+response.status+' code='+safeCode(data.error?.code??data.category??data.status)+' retryAfterMs='+delay+(read?'':' - reconcile before retry'));
 }
}
const bounded=(items)=>{if(JSON.stringify(items).length>2800000)throw new Error('Collected result exceeds 2.8MB bound; use smaller pages');};
const a=inputs.address;const root='/crm/objects/2026-09/'+segment(a.fromObjectType)+'/'+segment(a.fromId)+'/associations/';return {labels:await request('/crm/associations/2026-09/'+segment(a.fromObjectType)+'/'+segment(a.toObjectType)+'/labels')};

